\begin{align*}
\tan(\theta) &= \frac{\sin(\theta)}{\cos(\theta)} \\
&= \frac{2\left( \frac{x - 1}{2x}\right)^{\frac{1}{2}} \left( \frac{x + 1}{2x} \right)^{\frac{1}{2}}}{2\left( \frac{x+1}{2x}\right) - 1}
\end{align*}

