def calculate_orders(num):
    if num == 1:
        return {'answer': '1st place'}
    else:
        orders = []
        for i in range(num):
            current_order = calculate_orders(num - 1)
            if i == num - 1:
                order = dict(current_order.items())
                if current_order['answer'] != 'none of these':
